 "content": "def transform(grid):
    out = [row[:] for row in grid]
    pts = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == 1]
    if len(pts) < 2:
        return out
    dr = pts[1][0] - pts[0][0]
    dc = pts[1][1] - pts[0][1]
    if any((pts[i+1][0]-pts[i][0], pts[i+1][1]-pts[i][1]) != (dr, dc) for i in range(len(pts)-1)):
        return out
    r, c = pts[-1]
    while 0 <= r + dr < len(out) and 0 <= c + dc < len(out[0]):
        r += dr
        c += dc
        if out[r][c] == 0:
            out[r][c] = 2
    return out
